import time
from collections import OrderedDict
from typing import Any, Callable, List, Optional


class TTLCache:
    """
    A fixed‑size cache with per‑entry time‑to‑live (TTL) and LRU eviction policy.
    """

    def __init__(self, capacity: int, ttl: float, clock: Callable[[], float] = time.monotonic):
        if capacity < 1:
            raise ValueError("capacity must be at least 1")
        if ttl <= 0:
            raise ValueError("ttl must be greater than 0")
        self._capacity = capacity
        self._ttl = ttl
        self._clock = clock
        # OrderedDict preserves insertion order; we treat the end as most‑recently used.
        self._store: OrderedDict[Any, tuple[Any, float]] = OrderedDict()

    def _purge_expired(self) -> None:
        """Remove all expired entries, starting from the least‑recently used."""
        now = self._clock()
        # Since we may delete while iterating, we collect keys to delete.
        keys_to_delete = []
        for key, (_, expiry) in self._store.items():
            if now >= expiry:
                keys_to_delete.append(key)
            else:
                # OrderedDict is ordered; once we hit a non‑expired entry we can stop.
                break
        for key in keys_to_delete:
            self._store.pop(key, None)

    def put(self, key: Any, value: Any) -> None:
        """Insert or replace a value and set its expiry."""
        expiry = self._clock() + self._ttl
        # If key exists, delete it first to re‑insert at the end (most recent).
        if key in self._store:
            self._store.pop(key)
        self._store[key] = (value, expiry)  # inserted at the end
        # Ensure capacity constraints.
        self._purge_expired()
        while len(self._store) > self._capacity:
            # popitem(last=False) removes the least‑recently used entry.
            self._store.popitem(last=False)

    def get(self, key: Any) -> Optional[Any]:
        """Return the value for *key* if present and not expired; otherwise None."""
        if key not in self._store:
            return None
        value, expiry = self._store[key]
        now = self._clock()
        if now >= expiry:
            # Expired – remove and report miss.
            self._store.pop(key, None)
            return None
        # Refresh LRU order: move to end (most recent).
        self._store.move_to_end(key)
        return value

    def __len__(self) -> int:
        """Number of non‑expired entries."""
        self._purge_expired()
        return len(self._store)

    def keys(self) -> List[Any]:
        """List of non‑expired keys from least to most recently used."""
        self._purge_expired()
        return list(self._store.keys())

