import re
from typing import Any, Callable, Dict, List, Tuple, Union

Token = Tuple[str, Any]  # (type, value)


class Lexer:
    _num_re = re.compile(r'\d+(\.\d+)?')
    _id_re = re.compile(r'[A-Za-z_][A-Za-z0-9_]*')

    def __init__(self, text: str):
        self.text = text
        self.pos = 0
        self.current: Token = ('EOF', None)
        self._advance()

    def _skip_ws(self):
        while self.pos < len(self.text) and self.text[self.pos].isspace():
            self.pos += 1

    def _advance(self):
        self._skip_ws()
        if self.pos >= len(self.text):
            self.current = ('EOF', None)
            return

        ch = self.text[self.pos]

        if ch.isdigit():
            m = self._num_re.match(self.text, self.pos)
            if not m:
                raise ValueError(f"Invalid number at position {self.pos}")
            num_str = m.group(0)
            if '.' in num_str:
                if num_str.endswith('.'):
                    raise ValueError(f"Invalid number format at position {self.pos}")
                if num_str.startswith('.'):
                    raise ValueError(f"Invalid number format at position {self.pos}")
            self.pos = m.end()
            self.current = ('NUMBER', float(num_str))
        elif ch.isalpha() or ch == '_':
            m = self._id_re.match(self.text, self.pos)
            ident = m.group(0)
            self.pos = m.end()
            self.current = ('IDENT', ident)
        elif ch in '+-*/^(),':
            self.pos += 1
            typ = {
                '+': 'PLUS',
                '-': 'MINUS',
                '*': 'MUL',
                '/': 'DIV',
                '^': 'POW',
                '(': 'LPAREN',
                ')': 'RPAREN',
                ',': 'COMMA',
            }[ch]
            self.current = (typ, ch)
        else:
            raise ValueError(f"Unknown character '{ch}' at position {self.pos}")

    def peek(self) -> Token:
        return self.current

    def consume(self, expected_type: str) -> Any:
        typ, val = self.current
        if typ != expected_type:
            raise ValueError(f"Expected token {expected_type} but got {typ}")
        self._advance()
        return val


class Parser:
    def __init__(self, lexer: Lexer, variables: Dict[str, float]):
        self.lexer = lexer
        self.vars = variables

    def parse(self) -> float:
        if self.lexer.peek()[0] == 'EOF':
            raise ValueError("Empty expression")
        result = self.expr()
        if self.lexer.peek()[0] != 'EOF':
            raise ValueError("Trailing garbage")
        return result

    # expr -> term ((PLUS|MINUS) term)*
    def expr(self) -> float:
        left = self.term()
        while True:
            typ = self.lexer.peek()[0]
            if typ == 'PLUS':
                self.lexer.consume('PLUS')
                right = self.term()
                left = left + right
            elif typ == 'MINUS':
                self.lexer.consume('MINUS')
                right = self.term()
                left = left - right
            else:
                break
        return left

    # term -> unary ((MUL|DIV) unary)*
    def term(self) -> float:
        left = self.unary()
        while True:
            typ = self.lexer.peek()[0]
            if typ == 'MUL':
                self.lexer.consume('MUL')
                right = self.unary()
                left = left * right
            elif typ == 'DIV':
                self.lexer.consume('DIV')
                right = self.unary()
                if right == 0:
                    raise ValueError("Division by zero")
                left = left / right
            else:
                break
        return left

    # unary -> MINUS power | power
    def unary(self) -> float:
        typ = self.lexer.peek()[0]
        if typ == 'MINUS':
            self.lexer.consume('MINUS')
            # after unary minus, next must be a power (not another unary plus)
            val = self.power()
            return -val
        elif typ == 'PLUS':
            # unary plus not allowed
            raise ValueError("Unary plus is not allowed")
        else:
            return self.power()

    # power -> atom (POW power)?
    def power(self) -> float:
        left = self.atom()
        if self.lexer.peek()[0] == 'POW':
            self.lexer.consume('POW')
            right = self.power()  # right-associative
            left = left ** right
        return left

    # atom -> NUMBER | IDENT ( '(' args ')' )? | '(' expr ')'
    def atom(self) -> float:
        typ, val = self.lexer.peek()
        if typ == 'NUMBER':
            self.lexer.consume('NUMBER')
            return val
        elif typ == 'IDENT':
            name = self.lexer.consume('IDENT')
            if self.lexer.peek()[0] == 'LPAREN':
                # function call
                return self.function_call(name)
            else:
                # variable
                if name not in self.vars:
                    raise ValueError(f"Unknown variable '{name}'")
                return float(self.vars[name])
        elif typ == 'LPAREN':
            self.lexer.consume('LPAREN')
            inner = self.expr()
            if self.lexer.peek()[0] != 'RPAREN':
                raise ValueError("Unbalanced parentheses")
            self.lexer.consume('RPAREN')
            return inner
        else:
            raise ValueError(f"Unexpected token {typ}")

    def function_call(self, name: str) -> float:
        self.lexer.consume('LPAREN')
        args = self.argument_list()
        if self.lexer.peek()[0] != 'RPAREN':
            raise ValueError("Unbalanced parentheses in function call")
        self.lexer.consume('RPAREN')
        if name == 'abs':
            if len(args) != 1:
                raise ValueError("abs() takes exactly one argument")
            return abs(args[0])
        elif name == 'min':
            if len(args) == 0:
                raise ValueError("min() requires at least one argument")
            return min(args)
        elif name == 'max':
            if len(args) == 0:
                raise ValueError("max() requires at least one argument")
            return max(args)
        else:
            raise ValueError(f"Unknown function '{name}'")

    def argument_list(self) -> List[float]:
        args = []
        if self.lexer.peek()[0] == 'RPAREN':
            return args  # empty list, will be checked by caller
        while True:
            args.append(self.expr())
            if self.lexer.peek()[0] == 'COMMA':
                self.lexer.consume('COMMA')
                # prevent trailing comma like f(a,)
                if self.lexer.peek()[0] == 'RPAREN':
                    raise ValueError("Missing argument after comma")
            else:
                break
        return args


def evaluate(expr: str, variables: Union[Dict[str, Any], None] = None) -> float:
    """
    Evaluate an arithmetic expression according to the specified grammar.
    Returns the result as a float.
    Raises ValueError for any syntax or runtime error.
    """
    if variables is None:
        variables = {}
    # Ensure all variable values are numbers
    for k, v in variables.items():
        if not isinstance(v, (int, float)):
            raise ValueError(f"Variable '{k}' is not a number")
    lexer = Lexer(expr)
    parser = Parser(lexer, {k: float(v) for k, v in variables.items()})
    return parser.parse()

