"""INI parser for a small dialect.

The public function is ``parse_ini(text)`` which returns a dict mapping
section names to dicts of key/value strings.  Errors raise ``ValueError``
containing the offending line number (e.g. ``line 3``).
"""

from __future__ import annotations

import re
from typing import Dict


def parse_ini(text: str) -> Dict[str, Dict[str, str]]:
    """
    Parse *text* according to the specification and return a mapping
    ``section -> {key: value}``.

    Raises:
        ValueError: on any syntax error, with a message that contains
            ``line N`` where N is the 1‑based line number.
    """
    sections: Dict[str, Dict[str, str]] = {}
    current_section: str | None = None

    lines = text.split("\n")
    for lineno, raw_line in enumerate(lines, start=1):
        line = raw_line.strip()
        if not line:
            continue  # empty line

        # comment line
        if line[0] in ";#":
            continue

        # section header
        if line[0] == "[":
            if not line.endswith("]"):
                raise ValueError(f"line {lineno}: malformed section header")
            name = line[1:-1].strip()
            if not name:
                raise ValueError(f"line {lineno}: empty section name")
            current_section = name
            sections.setdefault(name, {})
            continue

        # key/value line
        if "=" not in line:
            raise ValueError(f"line {lineno}: missing '='")
        key_part, value_part = line.split("=", 1)
        key = key_part.strip()
        if not key:
            raise ValueError(f"line {lineno}: empty key")

        # determine the section for keys before any explicit section
        if current_section is None:
            current_section = ""
            sections.setdefault("", {})

        # parse the value
        value = _parse_value(value_part, lineno)

        # store, later wins
        sections[current_section][key] = value

    # Remove the empty‑key section if it stayed empty
    if "" in sections and not sections[""]:
        del sections[""]

    return sections


def _parse_value(value_part: str, lineno: int) -> str:
    """Parse the right‑hand side of a key/value line."""
    value_part = value_part.strip()
    if not value_part:
        return ""  # empty value is allowed

    if value_part[0] == '"':
        return _parse_quoted(value_part, lineno)
    else:
        return _parse_unquoted(value_part)


def _parse_unquoted(text: str) -> str:
    """
    Unquoted value: cut off an inline comment that starts with ';' or '#'
    preceded by whitespace.  Backslashes are left untouched.
    """
    for i, ch in enumerate(text):
        if ch in ";#" and i > 0 and text[i - 1].isspace():
            # comment starts here
            return text[:i].rstrip()
    return text


def _parse_quoted(text: str, lineno: int) -> str:
    """
    Parse a quoted value according to the rules:
    - starts with a double quote
    - ends at the next unescaped double quote
    - supports \" \\ \n \t escapes, anything else is an error
    - after the closing quote only whitespace or a comment may follow
    """
    i = 1  # position after the opening quote
    result_chars = []
    while i < len(text):
        ch = text[i]
        if ch == "\\":
            if i + 1 >= len(text):
                raise ValueError(f"line {lineno}: bad escape at end of quoted value")
            nxt = text[i + 1]
            if nxt == '"':
                result_chars.append('"')
            elif nxt == "\\":
                result_chars.append("\\")
            elif nxt == "n":
                result_chars.append("\n")
            elif nxt == "t":
                result_chars.append("\t")
            else:
                raise ValueError(f"line {lineno}: bad escape '\\{nxt}'")
            i += 2
        elif ch == '"':
            # closing quote found
            i += 1
            break
        else:
            result_chars.append(ch)
            i += 1
    else:
        # loop finished without finding a closing quote
        raise ValueError(f"line {lineno}: unterminated quoted value")

    # after closing quote: only whitespace or comment allowed
    rest = text[i:]
    if rest.strip() == "":
        # nothing else
        return "".join(result_chars)
    # allow optional whitespace then comment
    stripped = rest.lstrip()
    if stripped and stripped[0] in ";#":
        # comment – ok
        return "".join(result_chars)
    raise ValueError(f"line {lineno}: unexpected text after closing quote")


