class OutOfStock(Exception):
    """Raised when attempting to remove more items than are in stock."""
    pass


class Inventory:
    def __init__(self, stock=None):
        # Copy the provided stock dict to avoid external mutation.
        self._stock = dict(stock) if stock is not None else {}

    def stock(self, item):
        """Return the current quantity of *item* (0 if never seen)."""
        return self._stock.get(item, 0)

    def add(self, item, qty):
        """Add *qty* of *item* to the inventory.

        Raises:
            ValueError: If *qty* is zero or negative.
        """
        if qty <= 0:
            raise ValueError("Quantity to add must be positive")
        self._stock[item] = self.stock(item) + qty

    def remove(self, item, qty):
        """Remove *qty* of *item* from the inventory.

        Raises:
            ValueError: If *qty* is zero or negative.
            OutOfStock: If there is not enough stock to satisfy the removal.
        """
        if qty <= 0:
            raise ValueError("Quantity to remove must be positive")
        current = self.stock(item)
        if qty > current:
            raise OutOfStock(f"Not enough {item} in stock (requested {qty}, available {current})")
        # Safe to subtract now.
        new_qty = current - qty
        if new_qty:
            self._stock[item] = new_qty
        else:
            # Remove the key to keep the dict tidy.
            self._stock.pop(item, None)


def fulfil(inventory, order):
    """Attempt to fulfil an *order* against *inventory*.

    The operation is atomic: either all items are removed or none are.
    Returns the total number of items removed.

    Raises:
        ValueError: If any ordered quantity is zero or negative.
        OutOfStock: If any item cannot be supplied in the requested amount.
    """
    # Validate order quantities first.
    for item, qty in order.items():
        if qty <= 0:
            raise ValueError(f"Ordered quantity for {item} must be positive")

    # Check stock availability without mutating.
    for item, qty in order.items():
        if inventory.stock(item) < qty:
            raise OutOfStock(f"Not enough {item} in stock to fulfil order")

    # All checks passed; perform removals.
    total = 0
    for item, qty in order.items():
        inventory.remove(item, qty)
        total += qty
    return total

"""
Tiny template engine.

Functions:
    render(template: str, context: dict) -> str
"""

from __future__ import annotations
from dataclasses import dataclass
from typing import Any, List, Tuple, Optional


# -------------------- AST node definitions -------------------- #
@dataclass
class TextNode:
    text: str


@dataclass
class VarNode:
    path: str
    filter_name: Optional[str] = None


@dataclass
class IfNode:
    path: str
    negated: bool
    true_body: List[Any]
    false_body: List[Any]


@dataclass
class ForNode:
    var_name: str
    path: str
    body: List[Any]


# -------------------- Helper functions -------------------- #
def _resolve_path(context: dict, path: str) -> Any:
    """Resolve a dotted path against the given context.

    Returns None if any part cannot be resolved.
    """
    parts = path.split(".")
    if not parts:
        return None
    cur = context.get(parts[0])
    if cur is None:
        return None
    for part in parts[1:]:
        if isinstance(cur, dict):
            cur = cur.get(part)
        elif isinstance(cur, list) and part.isdigit():
            idx = int(part)
            if 0 <= idx < len(cur):
                cur = cur[idx]
            else:
                return None
        else:
            return None
        if cur is None:
            return None
    return cur


def _apply_filter(value: Any, name: str) -> str:
    """Apply a filter to a value and return the string result."""
    if name == "upper":
        return "" if value is None else str(value).upper()
    if name == "lower":
        return "" if value is None else str(value).lower()
    if name == "title":
        return "" if value is None else str(value).title()
    if name == "length":
        if value is None:
            return "0"
        try:
            return str(len(value))
        except Exception:
            return "0"
    raise ValueError(f"Unknown filter: {name}")


# -------------------- Parser -------------------- #
def _parse(template: str) -> List[Any]:
    pos = 0
    length = len(template)

    def parse_nodes(stop_tags: List[str]) -> Tuple[List[Any], Optional[str]]:
        nonlocal pos
        nodes: List[Any] = []

        while True:
            if pos >= length:
                if stop_tags:
                    raise ValueError("Unclosed tag")
                break

            if template.startswith("{{", pos):
                end = template.find("}}", pos + 2)
                if end == -1:
                    # treat opening as plain text
                    nodes.append(TextNode(template[pos : pos + 2]))
                    pos += 2
                    continue
                raw = template[pos + 2 : end].strip()
                if "|" in raw:
                    path_part, filter_part = map(str.strip, raw.split("|", 1))
                    filter_name = filter_part
                else:
                    path_part = raw
                    filter_name = None
                nodes.append(VarNode(path_part, filter_name))
                pos = end + 2
                continue

            if template.startswith("{%", pos):
                end = template.find("%}", pos + 2)
                if end == -1:
                    nodes.append(TextNode(template[pos : pos + 2]))
                    pos += 2
                    continue
                tag = template[pos + 2 : end].strip()
                pos = end + 2

                # ----- block tags ----- #
                if tag.startswith("if "):
                    condition = tag[3:].strip()
                    negated = False
                    if condition.startswith("not "):
                        negated = True
                        condition = condition[4:].strip()
                    true_body, stop = parse_nodes(["else", "endif"])
                    false_body: List[Any] = []
                    if stop == "else":
                        false_body, stop = parse_nodes(["endif"])
                    if stop != "endif":
                        raise ValueError("Mismatched if/endif")
                    nodes.append(IfNode(condition, negated, true_body, false_body))
                    continue

                if tag == "else":
                    if "else" in stop_tags:
                        return nodes, "else"
                    raise ValueError("Unexpected else tag")

                if tag == "endif":
                    if "endif" in stop_tags:
                        return nodes, "endif"
                    raise ValueError("Unexpected endif tag")

                if tag.startswith("for "):
                    rest = tag[4:].strip()
                    if " in " not in rest:
                        raise ValueError("Invalid for syntax")
                    var_name, path = map(str.strip, rest.split(" in ", 1))
                    body, stop = parse_nodes(["endfor"])
                    if stop != "endfor":
                        raise ValueError("Mismatched for/endfor")
                    nodes.append(ForNode(var_name, path, body))
                    continue

                if tag == "endfor":
                    if "endfor" in stop_tags:
                        return nodes, "endfor"
                    raise ValueError("Unexpected endfor tag")

                # any other tag is illegal
                raise ValueError(f"Unknown tag: {tag}")

            # ----- plain text ----- #
            next_var = template.find("{{", pos)
            next_block = template.find("{%", pos)
            next_pos_candidates = [i for i in (next_var, next_block) if i != -1]
            next_pos = min(next_pos_candidates) if next_pos_candidates else length
            text = template[pos:next_pos]
            nodes.append(TextNode(text))
            pos = next_pos

        return nodes, None

    ast, _ = parse_nodes([])
    return ast


# -------------------- Renderer -------------------- #
def _render_nodes(nodes: List[Any], context: dict) -> str:
    out: List[str] = []

    for node in nodes:
        if isinstance(node, TextNode):
            out.append(node.text)
        elif isinstance(node, VarNode):
            val = _resolve_path(context, node.path)
            if node.filter_name is None:
                out.append("" if val is None else str(val))
            else:
                out.append(_apply_filter(val, node.filter_name))
        elif isinstance(node, IfNode):
            test_val = _resolve_path(context, node.path)
            truth = bool(test_val)
            if node.negated:
                truth = not truth
            branch = node.true_body if truth else node.false_body
            out.append(_render_nodes(branch, context))
        elif isinstance(node, ForNode):
            iterable = _resolve_path(context, node.path)
            if isinstance(iterable, list):
                for item in iterable:
                    new_ctx = context.copy()
                    new_ctx[node.var_name] = item
                    out.append(_render_nodes(node.body, new_ctx))
            # missing or non‑list => render nothing
        else:
            # Should never happen
            raise ValueError("Invalid node type")
    return "".join(out)


# -------------------- Public API -------------------- #
def render(template: str, context: dict) -> str:
    """
    Render `template` using `context`.

    The template language follows the specification described in the module docstring.
    """
    ast = _parse(template)
    return _render_nodes(ast, context)
